// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Merkezî eğilim ve yayılım ölçüleri (her soru kendi verisini içerir) (zor).
const ozStatistics1Zor = <(String, String, List<String>, String)>[
  ('48 kişilik bir sınıfın not ortalaması hesaplanırken bir öğrencinin 47 olan notu yanlışlıkla 74 olarak girilmiş ve ortalama 63,5 bulunmuştur. Doğru ortalama kaçtır?', '62,9375', ['64,0625', '63,0', '62,5'], 'Yanlış toplam 48 · 63,5 = 3048\'dir. Doğru toplam 3048 − 74 + 47 = 3021 olur; 3021 / 48 = 62,9375.'),
  ('Bir ankette katılımcıların günlük sosyal medya süreleri gruplanmadan kaydedilmiş: 10 dk (6 kişi), 20 dk (4 kişi), 30 dk (5 kişi), 40 dk (5 kişi). Medyan süre kaç dakikadır?', '25', ['20', '30', '26,5'], '20 gözlemde medyan 10. ve 11. değerlerin ortalamasıdır. 10. değer 20, 11. değer 30 dakikadır; (20 + 30) / 2 = 25.'),
  ('Pearson\'un deneysel bağıntısına göre orta derecede çarpık tek tepeli dağılımlarda yaklaşık olarak Ortalama − Mod ≈ 3(Ortalama − Medyan) olur. Ortalaması 50, medyanı 47 olan böyle bir dağılımda mod yaklaşık kaçtır?', '41', ['44', '38,5', '53'], 'Ortalama − Mod ≈ 3 · (50 − 47) = 9 olduğundan Mod ≈ 50 − 9 = 41 bulunur.'),
  ('Bir veri setinin değişim katsayısı her değer 4 ile çarpıldığında nasıl değişir?', 'Değişmez', ['4 katına çıkar', '16 katına çıkar', 'Dörtte birine iner'], 'Değişim katsayısı σ / x̄ oranıdır. Çarpmada hem standart sapma hem ortalama 4 katına çıktığı için oran aynı kalır.'),
  ('Bir sitede 11 kullanıcının oturum süreleri (dakika) 12, 15, 16, 18, 19, 21, 22, 24, 25, 28, 60\'tır. 1,5 × IQR kuralına göre aykırı değerler için üst sınır kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '38,5', ['37', '34', '43,5'], 'Q1 = 16, Q3 = 25, IQR = 9\'dur. Üst sınır Q3 + 1,5 · IQR = 25 + 13,5 = 38,5 olur; 60 bu sınırı aştığı için aykırıdır.'),
  ('2, 8, 9, 10, 11, 12, 13, 14, 30 verisinde 1,5 × IQR kuralına göre hangi değerler aykırıdır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', 'Yalnız 30', ['2 ve 30', 'Yalnız 2', 'Aykırı değer bulunmaz'], 'Q1 = 8,5, Q3 = 13,5, IQR = 5\'tir. Sınırlar 8,5 − 7,5 = 1 ve 13,5 + 7,5 = 21 olur. 2 alt sınırın üstünde kaldığından aykırı değildir; yalnız 30 sınır dışıdır.'),
  ('Bir verinin beş sayı özeti 4, 20, 26, 30, 34\'tür. Dağılımın çarpıklığı için en makul yorum hangisidir?', 'Sola çarpıktır', ['Sağa çarpıktır', 'Tam simetriktir', 'Çarpıklık hakkında hiçbir ipucu yoktur'], 'Medyandan Q1\'e uzaklık (6) Q3\'e uzaklıktan (4), minimumun uzaklığı (22) maksimumunkinden (8) büyüktür. Sol taraf daha uzun olduğundan dağılım sola çarpıktır.'),
  ('Örneklem varyansı hesaplanırken kare sapmalar toplamı n yerine n − 1\'e bölünür. Bunun temel nedeni nedir?', 'Anakütle varyansını sistematik olarak küçük tahmin etmemek için', ['Hesabı kolaylaştırmak için', 'Aykırı değerlerin hesaba etkisini tamamen ortadan kaldırmak için', 'Sonucu standart sapmaya eşitlemek için'], 'Örneklem ortalaması verilere anakütle ortalamasından daha yakın olduğundan n\'ye bölmek varyansı küçük tahmin eder. n − 1 (Bessel düzeltmesi) bu yanlılığı giderir.'),
  ('Bir verinin ortalamasına eşit yeni bir gözlem eklenirse (n > 1 ve varyans sıfırdan büyükken) anakütle varyansı nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Sıfır olur'], 'Kare sapmalar toplamı aynı kalır ama bölen n\'den n + 1\'e çıkar; dolayısıyla varyans küçülür.'),
  ('Ortalaması 60, standart sapması 5 olan bir veride Çebişev eşitsizliğine göre 45 ile 75 arasındaki gözlemlerin oranı en az ne kadardır?', '8/9', ['3/4', '1/9', '15/16'], '45 ve 75 ortalamadan 15 = 3 standart sapma uzaktadır. En az 1 − 1/3² = 8/9 (yaklaşık %88,9) oranı bu aralıktadır.'),
  ('Çebişev eşitsizliğinin normal dağılım için verilen yüzdelerden temel farkı nedir?', 'Dağılımın biçimine bakmaksızın en az oranı garanti eder', ['Yalnız simetrik dağılımlarda geçerlidir', 'Kesin oranları verir, alt sınırı vermez', 'Yalnız gözlem sayısı çok küçük veri setlerinde kullanılabilir'], 'Çebişev her dağılım için geçerli bir alt sınır verir; bu nedenle normal dağılıma özgü yaklaşık oranlardan daha temkinlidir.'),
  ('Bir yatırım birinci yıl %44 değer kazanmış, ikinci yıl ise değeri hiç değişmemiştir. İki yılın yıllık ortalama (bileşik) büyüme oranı yüzde kaçtır?', '%20', ['%22', '%21', '%22,5'], 'Büyüme çarpanlarının geometrik ortalaması alınır: √(1,44 · 1,00) = 1,2. Yıllık ortalama büyüme %20\'dir; aritmetik ortalama (%22) yanıltıcıdır.'),
  ('İki pozitif sayının aritmetik ortalaması 10, geometrik ortalaması 8\'dir. Bu iki sayının harmonik ortalaması kaçtır?', '6,4', ['6', '9', '7,25'], 'İki sayı için G² = A · H bağıntısı vardır. 64 = 10 · H olduğundan H = 6,4 bulunur. Sayılar 4 ve 16\'dır; kontrol: 2 · 64 / 20 = 6,4.'),
  ('Bir işçi bir parçayı 10 dakikada, ikinci bir işçi aynı parçayı 15 dakikada üretiyor. İkisi eşit sayıda parça ürettiğinde parça başına ortalama süre kaç dakikadır?', '12,5', ['12', '11,75', '13'], 'Eşit sayıda parça üretildiğinde toplam süre / toplam parça = (10 + 15) / 2 = 12,5 dakikadır. Burada ortalanan süreler olduğu için aritmetik ortalama uygundur.'),
  ('İki musluk aynı süre boyunca çalışıyor: biri bir kovayı 10 dakikada, öteki 15 dakikada dolduruyor. İkisinin eşit süre çalıştığı durumda kova başına ortalama dolum süresi kaç dakikadır?', '12', ['12,5', '13,5', '11'], 'Eşit sürede ilk musluk 1/10, ikincisi 1/15 kova/dk doldurur. Kova başına ortalama süre harmonik ortalamadır: 2 / (1/10 + 1/15) = 12 dakika.'),
  ('Kırpma oranı giderek artırılıp her iki uçtan neredeyse bütün değerler atılırsa kırpılmış ortalama hangi ölçüye yaklaşır?', 'Medyana', ['Moda', 'Orta değere', 'Harmonik ortalamaya'], 'Yüzde 0 kırpma aritmetik ortalamayı verir; kırpma en uca götürüldüğünde yalnız ortadaki değer(ler) kalır, bu da medyandır.'),
  ('10 kişilik A grubunun ortalaması 20, varyansı 4; 10 kişilik B grubunun ortalaması 30, varyansı 9\'dur. Gruplar birleştirilince birleşik anakütle varyansı kaç olur?', '31,5', ['6,5', '13', '25'], 'Birleşik ortalama 25\'tir. Varyans = grup içi varyansların ortalaması + ortalamaların yayılımı = (4 + 9) / 2 + 25 = 6,5 + 25 = 31,5.'),
  ('İki grubun varyansları ayrı ayrı küçük olduğu hâlde birleştirildiklerinde varyansın çok büyümesinin nedeni nedir?', 'Grup ortalamaları birbirinden uzaktır', ['Grupların gözlem sayıları eşittir', 'Her iki grupta da aykırı değer yoktur', 'Grup varyansları birbirine eşittir'], 'Birleşik varyans, grup içi yayılım ile grup ortalamalarının ortak ortalamadan uzaklığından oluşur. Ortalamalar uzaksa ikinci bileşen büyür.'),
  ('1, 3, 4, 8, 9 verisi için |x − c| mutlak farklarının toplamını en küçük yapan c değeri kaçtır?', '4', ['5', '3', '4,5'], 'Mutlak sapmalar toplamını medyan en küçükler. Medyan 4 için toplam 13, ortalama 5 için 14\'tür.'),
  ('5 gözlemden oluşan bir verinin ortalaması 10, anakütle varyansı 4\'tür. Gözlemlerin karelerinin toplamı (Σx²) kaçtır?', '520', ['504', '540', '104'], 'Σx² / n = varyans + ortalama² = 4 + 100 = 104\'tür; 5 ile çarpınca Σx² = 520 bulunur.'),
  ('10 gözlemli bir verinin ortalaması 15, anakütle varyansı 9 bulunmuştur. Daha sonra 11 olan bir değerin yanlışlıkla 21 yazıldığı anlaşılmıştır. Düzeltilmiş varyans kaçtır?', '6', ['9', '4', '8,1'], 'Σx = 150 ve Σx² = 10 · (9 + 225) = 2340\'tır. Düzeltmeyle Σx = 140, Σx² = 2340 − 441 + 121 = 2020 olur. Varyans 202 − 14² = 6.'),
  ('9 gözlemli bir verinin anakütle varyansı 8\'dir. Ortalamaya eşit olan bir gözlem veriden çıkarılırsa yeni anakütle varyansı kaç olur?', '9', ['8', '7', '64/9'], 'Kare sapmalar toplamı 9 · 8 = 72\'dir ve çıkarılan değer bu toplama katkı yapmaz. Yeni varyans 72 / 8 = 9\'dur.'),
  ('Bir hareketli ortalamada pencere genişliği 3 günden 7 güne çıkarılırsa elde edilen eğri genellikle nasıl değişir?', 'Daha düzgün olur ama değişimlere daha geç tepki verir', ['Daha dalgalı olur ve değişimlere hemen tepki verir', 'Ham veriyle tamamen aynı olur', 'Her zaman ham verinin üstünde kalır ve değişimlere hiç tepki vermez'], 'Geniş pencere daha çok değeri ortaladığı için dalgalanmaları daha çok yumuşatır; ancak yeni bir değişimin etkisi ortalamaya daha yavaş yansır.'),
  ('3, 5, 6, 9, 30 verisinin medyan mutlak sapması (MAD: medyandan mutlak sapmaların medyanı) kaçtır?', '3', ['6', '9,6', '4'], 'Medyan 6\'dır. Mutlak sapmalar 3, 1, 0, 3, 24 olup sıralanınca 0, 1, 3, 3, 24 elde edilir; medyanı 3\'tür.'),
  ('Medyanı 15 olan 10, 12, 13, 15, 16, 18, 40 verisinde 40 değeri 400 yapılırsa aşağıdakilerden hangisi değişmez?', 'Medyan mutlak sapma', ['Ortalama', 'Standart sapma', 'Orta değer'], 'Medyan 15 kalır; medyandan mutlak sapmaların sıralaması da ortada aynı kalır (MAD = 3). Ortalama, standart sapma ve orta değer ise büyük değerle birlikte artar.'),
  ('1, 2, 3, …, 10 tam sayılarının anakütle varyansı kaçtır?', '8,25', ['9,17', '5,5', '10'], 'Ardışık n tam sayının anakütle varyansı (n² − 1) / 12\'dir: (100 − 1) / 12 = 8,25. 9,17 örneklem varyansıdır.'),
  ('2, 4, x, 10 verisinde 4 < x < 10\'dur. Verinin ortalaması medyanına eşitse x kaçtır?', '8', ['6', '7', '9'], 'Medyan (4 + x) / 2, ortalama (16 + x) / 4\'tür. 2(4 + x) = 16 + x denkleminden x = 8 bulunur.'),
  ('Bir şehirde ev fiyatlarının medyanı 2 milyon TL, ortalaması 3,1 milyon TL olarak açıklanmıştır. Bir gazeteci \'evlerin çoğu 3 milyonun üzerinde\' diye yazıyor. Bu yorum için ne söylenebilir?', 'Hatalıdır; evlerin en az yarısı 2 milyon TL ya da altındadır', ['Doğrudur; çünkü ortalama 3 milyonun üzerindedir', 'Doğrudur; çünkü medyan ortalamadan küçüktür', 'Verilen bilgilerle evlerin dağılımı hakkında yorum yapılamaz'], 'Medyan 2 milyon olduğundan evlerin en az yarısı bu değerin altında ya da ona eşittir; çoğunun 3 milyonun üzerinde olması imkânsızdır.'),
  ('Dokuz kişilik bir grubun yaş medyanı 30\'dur. Gruptan 30 yaşındaki kişi ayrılırsa yeni medyan hakkında hangisi kesindir?', 'Kalan sekiz kişide 4. ve 5. yaşın ortalamasıdır', ['Kesinlikle 30\'dur', 'Kesinlikle 30\'dan büyüktür', 'Kesinlikle 30\'dan küçüktür, çünkü ortadaki kişi çıkarılmıştır'], 'Ayrılan kişi ortadaki kişidir. Kalan 8 kişinin medyanı, eski 4. ve 6. kişinin yaşlarının ortalamasıdır; bu değer 30\'a eşit, küçük ya da büyük olabilir.'),
  ('Sıcaklık Celsius ölçeğinde ölçüldüğünde \'20 °C, 10 °C\'nin iki katı sıcaklıktır\' demek neden yanlıştır?', 'Celsius ölçeğinde sıfır noktası keyfîdir', ['Celsius ölçeği sınıflayıcı bir ölçektir', 'Sıcaklıkların ortalaması alınamaz', 'Sıcaklık yalnız sıralanabilen, farkları anlamsız bir değişkendir'], 'Celsius aralıklı bir ölçektir: farklar anlamlıdır ama 0 °C sıcaklığın yokluğu değildir. Bu yüzden oran yorumları geçersizdir.'),
  ('Altı değeri 6, yedinci değeri 20 olan bir veri setinin anakütle varyansı kaçtır?', '24', ['28', '14', '196/7'], 'Ortalama (36 + 20) / 7 = 8\'dir. Kare sapmalar altı kez 4 ve bir kez 144 olup toplamı 168\'dir; 168 / 7 = 24.'),
  ('Bir sınıfın puanlarının ortalaması 70, standart sapması 12\'dir. Her öğrencinin puanı ortalamaya doğru yarı yarıya çekilirse (yeni puan = 70 + (eski − 70)/2) yeni standart sapma kaç olur?', '6', ['12', '3', '35'], 'Dönüşüm y = 0,5x + 35 biçimindedir; standart sapma 0,5 · 12 = 6 olur. Ortalama ise 70\'te kalır.'),
  ('Çebişev eşitsizliğine göre verilerin en az %84\'ünün ortalamanın kaç standart sapma yakınında olduğu garanti edilir?', '2,5', ['2', '3', '1,84'], '1 − 1/k² = 0,84 eşitliğinden 1/k² = 0,16, k² = 6,25 ve k = 2,5 bulunur.'),
  ('Çebişev eşitsizliği ortalamadan 1 standart sapma uzaklık (k = 1) için ne söyler?', 'Hiçbir yararlı alt sınır vermez', ['Verilerin en az %68\'i bu aralıktadır', 'Verilerin en az %50\'si bu aralıktadır', 'Verilerin tamamı bu aralıktadır'], 'k = 1 için 1 − 1/1² = 0 bulunur; yani \'en az %0\' gibi bilgi taşımayan bir sınır elde edilir. Eşitsizlik k > 1 için anlamlıdır.'),
  ('Değişim katsayısının sıcaklığın Celsius cinsinden ölçüldüğü veriler için yanıltıcı olabilmesinin nedeni nedir?', 'Ortalama 0\'a yakın ya da negatif olabildiği için', ['Celsius verileri tam sayı olmadığı için', 'Sıcaklıkların standart sapması hesaplanamadığı için', 'Sıcaklık verileri sıralanamadığı için'], 'DK bir orana dayanır; ortalama 0\'a yaklaştıkça değer şişer, negatif ortalamada anlamını yitirir. Bu ölçü gerçek sıfırı olan oranlı ölçekler için uygundur.'),
  ('Bir kentin nüfusu 10 yılda iki katına çıkmıştır. Yıllık ortalama (bileşik) artış oranı yaklaşık yüzde kaçtır?', '%7,2', ['%10', '%20', '%5'], 'Yıllık çarpan r için r¹⁰ = 2\'dir; r = 2^(1/10) ≈ 1,072. Yıllık ortalama artış yaklaşık %7,2\'dir. %10 basit bölmeyle bulunur ve bileşik büyümeyi abartır.'),
  ('Bir ürünün fiyatı üç yıl üst üste %10 artmış, %20 artmış ve %10 azalmıştır. Yıllık ortalama değişim oranı yaklaşık yüzde kaçtır?', '%5,9', ['%6,7', '%6,0', '%4,8'], 'Çarpanların geometrik ortalaması ∛(1,1 · 1,2 · 0,9) = ∛1,188 ≈ 1,059\'dur; ortalama artış yaklaşık %5,9. Yüzdelerin aritmetik ortalaması (%6,7) yanıltıcıdır.'),
  ('Bir bakteri kolonisinin dört ardışık ölçümdeki büyüklüğü (bin hücre) 1, 3, 9 ve 27 olarak bulunmuştur. Bu ölçümlerin geometrik ortalaması kaç bin hücredir?', '3√3', ['10', '9', '√27 / 2'], 'Çarpım 729 = 3⁶\'dır; dördüncü kökü 3^(6/4) = 3^1,5 = 3√3 ≈ 5,2\'dir.'),
  ('Bir bisiklet turunun eşit uzunluktaki üç etabında ortalama hızlar saatte 40, 60 ve 120 km\'dir. Turun tamamında ortalama hız saatte kaç km\'dir?', '60', ['73,3', '66', '80'], 'Eşit mesafelerde harmonik ortalama kullanılır: 3 / (1/40 + 1/60 + 1/120) = 3 / (6/120) = 60 km/sa.'),
  ('Bir sürücü iki ayrı alışverişte her seferinde 600 TL\'lik yakıt alıyor; litre fiyatı ilk seferde 30 TL, ikincide 60 TL\'dir. Ödediği ortalama litre fiyatı kaç TL\'dir?', '40', ['45', '42,5', '50'], 'İlk seferde 20, ikincide 10 litre alınır; 1200 TL / 30 litre = 40 TL. Harcanan para sabit olduğunda fiyatların harmonik ortalaması gerekir.'),
  ('Pozitif sayılardan oluşan bir veride aritmetik ortalama ile geometrik ortalama eşit çıkmıştır. Bu veri için ne söylenebilir?', 'Tüm değerler birbirine eşittir', ['Değerler ardışık tam sayılardır', 'Değerlerin yarısı ortalamanın altındadır', 'Veride tam iki farklı değer vardır'], 'AO–GO eşitsizliğinde eşitlik ancak bütün değerler eşit olduğunda sağlanır; aksi hâlde AO kesinlikle GO\'dan büyüktür.'),
  ('Bir verinin sınıfları ve frekansları şöyledir: 0–10: 4, 10–20: 6, 20–30: 8, 30–40: 2. Gruplanmış veride medyan formülü (L + ((n/2 − F) / f) · h) kullanılırsa medyan kaçtır?', '20', ['15', '25', '22,5'], 'n/2 = 10\'dur. Birikimli frekanslar 4 ve 10 olduğundan 10. gözlem 10–20 sınıfının sonuna düşer: 10 + ((10 − 4) / 6) · 10 = 20.'),
  ('Açıklığı 10 olan bir verinin anakütle standart sapması aşağıdakilerden hangisi olamaz?', '6', ['2', '4', '5'], 'Anakütle standart sapması açıklığın yarısını aşamaz. En büyük değer (5), gözlemlerin yarısı en küçük, yarısı en büyük değerdeyken elde edilir; 6 imkânsızdır.'),
  ('Bir değişkenin ortalaması 0, standart sapması 1 olarak verilmiştir. Bu bilgiye göre hangisi kesinlikle doğrudur?', 'Değerlerin kareleri ortalaması 1\'dir', ['Bütün değerler −1 ile 1 arasındadır', 'Değerlerin yarısı negatiftir', 'Medyan 0\'dır'], 'Varyans = x² ortalaması − ortalama² olduğundan 1 = x² ortalaması − 0, yani karelerin ortalaması 1\'dir. Diğerleri dağılıma bağlıdır.'),
  ('Bir dağılımın birinci çeyreği 50, medyanı 52, üçüncü çeyreği 70\'tir. Ortadaki %50\'lik dilimin biçimi için ne söylenebilir?', 'Sağa çarpıktır', ['Sola çarpıktır', 'Simetriktir', 'İki tepelidir'], 'Medyandan Q3\'e uzaklık (18), Q1\'e uzaklıktan (2) çok büyüktür; üst taraf uzadığı için orta dilim sağa çarpıktır.'),
  ('Bir veri setinde Q1 = Q3 olduğu biliniyor. Bu durumda çeyrekler açıklığı kaçtır ve bu ne gösterir?', '0\'dır; ortadaki gözlemler tek bir değerde toplanmıştır', ['1\'dir; veri simetriktir', 'Medyana eşittir; veri çarpıktır', 'Tanımsızdır; çünkü bu durumda verinin hatalı girildiği kesindir'], 'IQR = Q3 − Q1 = 0 ise orta %50\'lik dilimin değerleri birbirine eşittir; uçlarda farklı değerler yine bulunabilir.'),
  ('Bir veride 1,5 × IQR kuralıyla alt sınır 12, üst sınır 52 bulunmuştur. Q1 kaçtır?', '27', ['22', '32', '37'], 'Sınırlar arası fark 40 = IQR + 3 · IQR = 4 · IQR olduğundan IQR = 10\'dur. Q1 = 12 + 15 = 27, Q3 = 52 − 15 = 37.'),
  ('Bir verinin ortalaması 4 ve varyansı 9\'dur. Her gözlemin karesi alınırsa yeni verinin ortalaması kaç olur?', '25', ['16', '13', '81'], 'x² ortalaması = varyans + ortalama² = 9 + 16 = 25\'tir.'),
  ('Anakütle varyansı σ² = Σ(xᵢ − μ)² / N, örneklem varyansı s² = Σ(xᵢ − x̄)² / (n − 1) biçiminde yazılır. Aynı 5 değer için s² ile σ² arasındaki ilişki hangisidir?', 's² = (5/4) · σ²', ['s² = (4/5) · σ²', 's² = σ²', 's² = σ² − 1'], 'Pay aynıdır; paydalar 4 ve 5\'tir. Dolayısıyla s² / σ² = 5 / 4 olur.'),
  ('\'Varyans\' terimini 1918\'de istatistiğe kazandıran bilim insanı kimdir?', 'Ronald Fisher', ['Karl Pearson', 'Francis Galton', 'Pierre-Simon Laplace'], 'R. A. Fisher 1918\'de kalıtımla ilgili makalesinde \'variance\' terimini standart sapmanın karesi anlamında kullandı.'),
  ('Bir kuşçu beş günde gördüğü kuş türü sayılarını 3, 5, 5, 8 ve k olarak not etmiştir. Bu sayıların ortalaması tek modlarına eşittir. k tam sayısı kaçtır?', '4', ['5', '6', '9'], 'k = 3 ya da k = 8 olursa iki mod oluşur. Mod 5 kalırken ortalamanın 5 olması için toplam 25 olmalıdır: 21 + k = 25, k = 4.'),
  ('x − d, x, x + d biçimindeki üç sayının (d > 0) anakütle standart sapması hangisidir?', 'd·√(2/3)', ['d', '2d/3', 'd²'], 'Kare sapmalar d², 0, d² olup toplamı 2d²\'dir. Varyans 2d² / 3, standart sapma d·√(2/3) olur.'),
  ('Bir şirketteki maaşlara %10 zam yerine herkese eşit miktarda sabit zam yapılırsa maaşların değişim katsayısı nasıl etkilenir?', 'Azalır', ['Artar', 'Değişmez', 'Sıfır olur'], 'Sabit zam standart sapmayı değiştirmez ama ortalamayı büyütür; σ / x̄ oranı küçülür. Yüzde zamda ise DK aynı kalır.'),
  ('Bir öğrencinin 5 sınavlık hareketli ortalaması 72\'dir. Yeni bir sınav eklenip en eski sınav (60) pencereden çıkınca hareketli ortalama 75 oluyor. Yeni sınavın puanı kaçtır?', '75', ['63', '15', '90'], 'Eski pencerenin toplamı 360\'tır. Yeni toplam 5 · 75 = 375 olmalı; 360 − 60 + x = 375 eşitliğinden x = 75 bulunur.'),
  ('Ortalamaları eşit (10) ve gözlem sayıları eşit (5\'er) iki grubun varyansları 4 ve 16\'dır. Gruplar birleştirilirse birleşik anakütle varyansı kaç olur?', '10', ['20', '6', '12,5'], 'Ortalamalar eşit olduğundan gruplar arası katkı sıfırdır; birleşik varyans grup varyanslarının ağırlıklı ortalamasıdır: (5 · 4 + 5 · 16) / 10 = 10.'),
  ('Ortalaması 50, varyansı 16 olan 20 kişilik grup ile ortalaması 60, varyansı 25 olan 30 kişilik grup birleştiriliyor. Birleşik anakütle varyansı kaçtır?', '45,4', ['21,4', '20,5', '41'], 'Grup içi katkı (20 · 16 + 30 · 25) / 50 = 21,4; gruplar arası katkı (20 · 36 + 30 · 16) / 50 = 24\'tür. Toplam 45,4 olur.'),
  ('Gruplanmış bir veride sınıflar 0–20: 6, 20–40: 9, 40–60: 5 frekanslıdır. L + ((n/2 − F) / f) · h formülüyle medyan yaklaşık kaçtır?', '28,9', ['30', '20', '25,6'], 'n/2 = 10, medyan sınıfı 20–40\'tır (F = 6, f = 9, h = 20). 20 + (4 / 9) · 20 ≈ 28,9.'),
  ('Çebişev eşitsizliğine göre ortalamadan 1,5 standart sapma içinde kalan gözlemlerin oranı en az ne kadardır?', 'Yaklaşık %55,6', ['%33,3', '%66,7', 'Yaklaşık %86,6'], '1 − 1/1,5² = 1 − 1/2,25 = 1 − 0,444 ≈ 0,556.'),
  ('Ortalaması 100 ve standart sapması 15 olan bir veride Çebişev eşitsizliğine göre değerlerin en çok yüzde kaçı 40\'ın altında ya da 160\'ın üstünde olabilir?', '%6,25', ['%5', '%0,3', '%25'], '40 ve 160 ortalamadan 60 = 4σ uzaktadır. Bu aralığın dışında en çok 1/4² = 1/16 = %6,25 gözlem olabilir.'),
  ('Bir laboratuvarda beş ölçümde bir çözeltinin pH değerleri 3,2; 3,8; 4,1; 4,5; 5,4 bulunmuştur. Beş ölçüm anakütle sayılırsa varyans kaçtır?', '0,54', ['0,675', '0,73', '0,45'], 'Ortalama 4,2\'dir. Kare sapmalar 1,00; 0,16; 0,01; 0,09; 1,44 toplamı 2,70\'tir; 2,70 / 5 = 0,54. 0,675 örneklem varyansıdır.'),
  ('1, 4, 4, 7 verisinin anakütle standart sapması aşağıdakilerden hangisidir?', '3/√2', ['3', '1,5', '√6'], 'Ortalama 4\'tür. Kare sapmalar 9, 0, 0, 9 toplamı 18; varyans 18 / 4 = 4,5 ve standart sapma √4,5 = 3/√2 ≈ 2,12\'dir. √6 örneklem standart sapmasıdır.'),
  ('Bir kütüphane 20 üyesinin bir ayda geciktirdiği kitap sayılarını kaydetmiştir: 0 kitap 10 kişi, 1 kitap 6 kişi, 2 kitap 3 kişi, 3 kitap 1 kişi. Medyan kaçtır?', '0,5', ['0', '1', '0,75'], 'Medyan 10. ve 11. değerlerin ortalamasıdır. 10. değer 0, 11. değer 1 olduğundan medyan 0,5\'tir. 0,75 ortalamadır.'),
  ('Bir veride 10 değeri 1 kez, 20 değeri 3 kez, 30 değeri 3 kez, 40 değeri 1 kez görülmektedir. Anakütle varyansı kaçtır?', '75', ['100', '8,66', '125'], 'Ortalama 200 / 8 = 25\'tir. Kare sapmalar toplamı 225 + 3 · 25 + 3 · 25 + 225 = 600; 600 / 8 = 75.'),
  ('10 kişilik bir grupta günlük uyku süreleri: 5 saat 3 kişi, 7 saat 6 kişi, 9 saat 1 kişi. Anakütle standart sapması kaç saattir?', '1,2', ['1,44', '1,6', '2'], 'Ortalama (15 + 42 + 9) / 10 = 6,6 saattir. Kare sapmalar toplamı 3 · 2,56 + 6 · 0,16 + 1 · 5,76 = 14,4; varyans 1,44, standart sapma 1,2 saattir.'),
  ('19. yüzyılda bazı toplumlarda doğumda beklenen yaşam süresinin yaklaşık 40 yıl olması, yetişkinlerin çoğunun 40 yaş civarında öldüğünü mü gösterir?', 'Hayır; bebek ölümlerinin yüksekliği ortalamayı aşağı çekmiştir', ['Evet; ortalama tipik ölüm yaşını gösterir', 'Evet; çünkü medyan da kesinlikle 40\'tır', 'Hayır; çünkü ortalama hep medyandan büyüktür'], 'Çok küçük yaştaki çok sayıda ölüm düşük uçta bir yığılma oluşturur ve ortalamayı düşürür; çocukluğu atlatanların çoğu 40\'ın çok üzerinde yaşayabilmiştir.'),
  ('A verisinin medyanı 10, B verisinin medyanı 20\'dir. İki veri birleştirildiğinde birleşik medyan için kesin olarak ne söylenebilir?', '10 ile 20 arasında (uçlar dâhil) bir değerdir', ['Kesinlikle 15\'tir', '20\'den büyük olabilir', '10\'dan küçük olabilir'], 'Birleşik verinin en az yarısı 20\'ye eşit ya da küçük, en az yarısı 10\'a eşit ya da büyüktür; bu yüzden birleşik medyan 10 ile 20 arasında kalır. Tam değeri veri sayılarına bağlıdır.'),
  ('Aşağıdaki veri setlerinin hangisinde anakütle standart sapması ortalamadan büyüktür?', '0, 0, 0, 10', ['9, 10, 11', '5, 6, 7, 8', '20, 20, 30'], '0, 0, 0, 10 verisinde ortalama 2,5, standart sapma yaklaşık 4,33\'tür. Diğer setlerde değerler ortalama etrafında sıkı toplandığından standart sapma ortalamadan küçüktür.'),
  ('Bir veri setinde ortalama ile medyanın eşit olması dağılımın simetrik olduğunu kesin olarak gösterir mi?', 'Hayır; simetrik olmayan veride de eşitlik görülebilir', ['Evet; eşitlik yalnız simetrik veride olur', 'Evet; ayrıca mod da aynı değere eşit olur', 'Hayır; çünkü bu eşitlik hiçbir veride gerçekleşmez'], 'Örneğin 1, 3, 4, 6, 6 verisinde ortalama ve medyan 4\'tür, ancak değerlerin medyana uzaklıkları (−3, −1, 0, 2, 2) simetrik değildir.'),
  ('100 kişilik bir sınavın ortalaması 80\'dir. Bu kişilerden 85\'inin ortalaması 78 ise kalan 15 kişinin ortalaması yaklaşık kaçtır?', '91,3', ['82', '92,5', '88,7'], 'Toplam 8000, 85 kişinin toplamı 6630\'dur. Kalan 15 kişinin toplamı 1370 olup 1370 / 15 ≈ 91,3\'tür.'),
  ('Bir ilçede 3 köyün nüfusları 200, 500 ve 300; hane başına düşen ortalama hayvan sayıları sırasıyla 4, 2 ve 6\'dır. Köylerin hane sayıları bilinmiyorsa ilçenin hane başına ortalama hayvan sayısı hakkında ne söylenebilir?', 'Hane sayıları bilinmeden kesin olarak hesaplanamaz', ['Kesinlikle 4\'tür', 'Nüfusla ağırlıklandırılırsa kesinlikle bulunur', 'Kesinlikle 3,4\'tür'], 'Hane başına ortalamaları birleştirmek için ağırlık olarak hane sayıları gerekir. Nüfus sayıları hane sayılarıyla orantılı olmayabileceğinden kesin sonuç bulunamaz.'),
  ('Bir öğrenci 4 kredilik bir dersten 2,0, 2 kredilik bir dersten 4,0 almıştır. Ortalamasını 3,0\'a çıkarmak için 2 kredilik üçüncü bir dersten kaç alması gerekir?', '4,0', ['3,0', '3,5', 'Bu mümkün değildir'], 'Hedef toplam 8 kredi · 3,0 = 24\'tür. Mevcut toplam 8 + 8 = 16\'dır; 2 kredilik derse 8 puan-kredi gerekir, yani not 4,0 olmalıdır.'),
  ('Aynı veri için ortalama mutlak sapma (OMS) ile anakütle standart sapması (σ) arasında her zaman hangi ilişki vardır?', 'OMS ≤ σ', ['OMS ≥ σ', 'OMS = σ²', 'OMS = 2σ'], 'Kare ortalamanın karekökü, mutlak değerlerin ortalamasından küçük olamaz; eşitlik yalnız bütün sapmaların mutlak değerce eşit olduğu durumda sağlanır.'),
  ('Bir sınavda 70 puanın z-puanı −1, 90 puanın z-puanı 1,5\'tir. Sınavın ortalaması ve standart sapması nedir?', 'Ortalama 78, standart sapma 8', ['Ortalama 80, standart sapma 10', 'Ortalama 78, standart sapma 10', 'Ortalama 75, standart sapma 8'], 'İki puan arasındaki 20 puanlık fark 2,5 standart sapmaya karşılık gelir: σ = 8. Ortalama 70 + 8 = 78\'dir.'),
  ('Bir veri setindeki bütün değerler −1 ile çarpılırsa her gözlemin z-puanı nasıl değişir?', 'İşareti tersine döner', ['Değişmez', 'Karesi alınır', 'Sıfır olur'], 'Yeni ortalama −x̄, standart sapma aynıdır: (−x − (−x̄)) / σ = −(x − x̄) / σ. Ortalamanın üstündeki değerler altına geçer.'),
  ('Bir verinin aritmetik ortalaması 6, anakütle standart sapması 8\'dir. Bu verinin karesel ortalaması kaçtır?', '10', ['14', '7', '100'], 'Karelerin ortalaması = σ² + x̄² = 64 + 36 = 100\'dür; karesel ortalama √100 = 10 olur.'),
  ('Aritmetik ortalaması 13, geometrik ortalaması 12 olan iki pozitif sayı hangileridir?', '8 ve 18', ['6 ve 20', '9 ve 17', '12 ve 14'], 'Toplam 26, çarpım 144\'tür. t² − 26t + 144 = 0 denkleminin kökleri 8 ve 18\'dir.'),
  ('8 gözlemli bir verinin ortalaması x̄, anakütle varyansı 5\'tir. Veriye x̄ + 3 ve x̄ − 3 değerleri eklenirse yeni anakütle varyansı kaç olur?', '5,8', ['5', '6,8', '4,6'], 'Ortalama değişmez. Kare sapmalar toplamı 8 · 5 = 40\'tan 40 + 9 + 9 = 58\'e çıkar; 58 / 10 = 5,8.'),
  ('Ortalaması 5 ve anakütle varyansı 6 olan üç sayıdan biri 5\'tir. Diğer iki sayı hangileridir?', '2 ve 8', ['1 ve 9', '3 ve 7', '4 ve 6'], 'Diğer iki sayının toplamı 10\'dur. Kare sapmalar toplamı 18 olmalı ve 5\'in katkısı 0 olduğundan iki sayı ortalamadan ±3 uzaktadır: 2 ve 8.'),
  ('x verisi y = (x − 10) / 2 dönüşümüyle y verisine çevriliyor. y\'nin ortalaması 3, varyansı 4 ise x\'in ortalaması ve varyansı nedir?', '16 ve 16', ['16 ve 8', '13 ve 16', '16 ve 4'], 'x = 2y + 10\'dur. Ortalama 2 · 3 + 10 = 16; varyans 2² · 4 = 16 olur.'),
  ('Beş tam sayının ortalaması 10, medyanı 12 ve tek modu 13\'tür. Bu sayıların en büyüğü kaçtır?', '13', ['14', '26', '12'], 'Medyan 12 olduğundan iki sayı 12\'den büyük ya da ona eşittir. Mod 13 en az iki kez geçmeli; bu yüzden 4. ve 5. sayılar 13\'tür. Kalan iki sayının toplamı 50 − 38 = 12\'dir.'),
  ('Bir veri setinin ortalaması 40\'tır. Değerlerin yarısı 10 artırılır, diğer yarısı 10 azaltılırsa yeni ortalama ve standart sapma için hangisi doğrudur?', 'Ortalama değişmez; standart sapma değişebilir', ['Ortalama 10 artar; standart sapma değişmez', 'Ortalama ve standart sapma değişmez', 'Ortalama 20 artar; standart sapma azalır'], 'Toplam artış ve azalış birbirini götürür, ortalama 40 kalır. Hangi değerlerin artırıldığına bağlı olarak yayılım artabilir ya da azalabilir.'),
  ('Bir öğretmen, sınıfın en az yarısının geçmesini istiyor ve geçme notunu buna göre belirleyecek. Hangi ölçünün altında kalan bir geçme notu bu hedefi garanti eder?', 'Medyanın', ['Ortalamanın', 'Modun', 'Orta değerin'], 'Geçme notu medyanın altındaysa medyana eşit ya da ondan yüksek puan alan öğrenciler, yani sınıfın en az yarısı geçer. Ortalama bunu garanti etmez; çarpık bir dağılımda öğrencilerin çoğu ortalamanın altında kalabilir.'),
  ('2, 4, 6, 8, 20 verisi için ortalamadan ortalama mutlak sapma (OMS) ve medyan mutlak sapma (MAD) değerleri sırasıyla nedir?', '4,8 ve 2', ['4,8 ve 4', '2 ve 4,8', '6 ve 2'], 'Ortalama 8; mutlak sapmalar 6, 4, 2, 0, 12 → OMS = 24 / 5 = 4,8. Medyan 6; mutlak sapmalar 4, 2, 0, 2, 14 → sıralı 0, 2, 2, 4, 14, MAD = 2.'),
  ('Bir veride medyan 50 ve medyan mutlak sapma (MAD) 6\'dır. Bu bilgiye göre aşağıdakilerden hangisi doğrudur?', 'Gözlemlerin en az yarısı 44 ile 56 arasındadır', ['Gözlemlerin tamamı 44 ile 56 arasındadır', 'Standart sapma 6\'dır', 'Ortalama 50\'dir'], 'MAD, medyandan mutlak sapmaların medyanıdır; dolayısıyla gözlemlerin en az yarısının medyana uzaklığı 6 ya da daha azdır.'),
  ('1, 2 ve 3 değerlerinin frekansları sırasıyla 4, f ve 6\'dır. Verinin ortalaması 2,1 ise f kaçtır?', '10', ['6', '8', '12'], '(4 + 2f + 18) / (10 + f) = 2,1 denkleminden 22 + 2f = 21 + 2,1f ve f = 10 bulunur.'),
  ('Bir araştırmada yaşlar 0–10, 10–20, 20–40 ve 40–80 biçiminde eşit olmayan genişlikte sınıflara ayrılmıştır. Bu durumda modal sınıfı belirlemek için yalnız frekanslara bakmak neden yanıltıcı olabilir?', 'Geniş sınıflar daha çok gözlem toplayabildiği için', ['Orta noktalar hesaplanamadığı için', 'Frekansların toplamı değiştiği için', 'Sınıflar sıralanamadığı için'], 'Eşit olmayan genişliklerde yoğunluk (frekans / genişlik) karşılaştırılmalıdır; yoksa yalnız geniş olduğu için çok gözlem içeren sınıf modal sanılabilir.'),
  ('Bir fabrikada 400 ampulün ömürlerinin ortalaması 1000 saat, standart sapması 50 saattir. Çebişev eşitsizliğine göre ömrü 900 ile 1100 saat arasında olan ampul sayısı en az kaçtır?', '300', ['380', '200', '100'], '900 ve 1100 ortalamadan 2σ uzaktadır. En az 1 − 1/4 = %75 oranı bu aralıktadır: 400 · 0,75 = 300 ampul.'),
  ('Ortalaması 70 ve standart sapması 5 olan bir veride, Çebişev eşitsizliğine göre gözlemlerin en az 8/9\'unu içeren ve ortalamaya göre simetrik olan aralık hangisidir?', '55 ile 85 arası', ['60 ile 80 arası', '62,5 ile 77,5 arası', '65 ile 75 arası'], '1 − 1/k² = 8/9 için k = 3\'tür. Aralık 70 ± 3 · 5, yani 55 ile 85 arasıdır.'),
  ('Beş yıl önce dört kişilik bir ailenin yaş ortalaması 22 idi. Bu arada aileye bir bebek katılmış ve bugün beş kişinin yaş ortalaması yine 22\'dir. Bebek kaç yaşındadır?', '2', ['5', '1', '0'], 'Dört kişinin bugünkü yaş toplamı 4 · 27 = 108\'dir. Beş kişinin toplamı 5 · 22 = 110 olduğundan bebek 2 yaşındadır.'),
  ('Bir sınıfın Türkçe puanlarının ortalaması 72\'dir. Öğretmen \'ortalamanın üstünde kalan öğrenci sayısı ortalamanın altında kalanlara eşittir\' diyor. Bu ifade hangi koşulda kesinlikle doğrudur?', 'Dağılım ortalama etrafında simetrikse', ['Standart sapma küçükse', 'Öğrenci sayısı çiftse', 'Mod 72\'den büyükse'], 'Ortalamanın iki yanındaki gözlem sayılarının eşitliği genel olarak garanti değildir; simetrik bir dağılımda ise ortalama medyana eşit olur ve iki taraf dengelenir.'),
  ('İki gözlemli bir verinin değerleri a ve b\'dir. Anakütle standart sapması hangi ifadeyle verilir?', '|a − b| / 2', ['|a − b|', '(a + b) / 2', '√(a · b)'], 'Ortalama (a + b) / 2\'dir ve her iki değer ortalamadan |a − b| / 2 uzaktadır; kare sapmaların ortalaması (a − b)² / 4 olduğundan σ = |a − b| / 2.'),
  ('İki veri setinin açıklıkları sırasıyla 10 ve 20\'dir. İki set birleştirildiğinde birleşik açıklık için kesin olarak ne söylenebilir?', 'En az 20\'dir', ['Tam 30\'dur', 'Tam 15\'tir', 'En çok 20\'dir'], 'Birleşik verinin en büyük ve en küçük değeri her iki setinkileri kapsar; bu yüzden birleşik açıklık iki açıklığın büyüğünden küçük olamaz.'),
  ('Pearson çarpıklık katsayısı Sk = 3 · (Ortalama − Medyan) / Standart sapma biçiminde tanımlanır. Ortalaması 54, medyanı 58, standart sapması 8 olan bir sınav için Sk kaçtır?', '−1,5', ['1,5', '−0,5', '−4'], 'Sk = 3 · (54 − 58) / 8 = −12 / 8 = −1,5. Negatif değer sola çarpıklığa işaret eder.'),
  ('Bir öğretmen sınav puanlarının ortalamasını 65, standart sapmasını 15 buluyor. Puanların 0–100 arasında olduğu biliniyorsa aşağıdakilerden hangisi kesinlikle doğrudur?', 'En az bir öğrenci 65\'in üstünde, en az biri altında puan almıştır', ['Hiçbir öğrenci 95\'in üstünde puan almamıştır', 'Öğrencilerin yarısı 50 ile 80 arasındadır', 'Puanların modu 65\'tir'], 'Standart sapma 0\'dan büyük olduğundan bütün puanlar eşit değildir; ortalamadan farklı puanlar bulunduğu için hem üstünde hem altında değer olmak zorundadır.'),
  ('Bir sınıfta 20 öğrencinin boy ortalaması hesaplanırken bir öğrencinin boyu iki kez yazılmış ve 21 değerle ortalama 160 cm bulunmuştur. İki kez yazılan boy 181 cm ise doğru ortalama kaç cm\'dir?', '158,95', ['159', '160', '161,05'], 'Yanlış toplam 21 · 160 = 3360\'tır. Fazladan yazılan 181 çıkarılınca 3179 kalır; 3179 / 20 ≈ 158,95 cm.'),
  ('Bir dükkân üç yıl boyunca cirosunu sırasıyla %5, %10 ve %20 artırmıştır. Yıllık ortalama (bileşik) artış oranı yaklaşık yüzde kaçtır?', '%11,5', ['%11,7', '%12,0', '%10,0'], 'Çarpanların geometrik ortalaması ∛(1,05 · 1,10 · 1,20) = ∛1,386 ≈ 1,115\'tir; ortalama artış yaklaşık %11,5. Aritmetik ortalama (%11,67) biraz yüksek kalır.'),
  ('Bir veride ortalamanın üstündeki her değer 10 artırılır, diğerleri aynı bırakılırsa standart sapma için hangisi doğrudur?', 'Artar', ['Azalır', 'Değişmez', 'Sıfır olur'], 'Ortalamanın üstündeki değerler ortalamadan daha da uzaklaşır; ortalama da bir miktar artsa bile yayılım büyür.'),
  ('Bir derste öğretmen notları \'ortalaması 70, standart sapması 10\' olacak biçimde ölçeklemek istiyor. Ham notların ortalaması 60, standart sapması 5\'tir. Ham notu 65 olan öğrencinin yeni notu kaç olur?', '80', ['75', '70', '85'], 'Ham notun z-puanı (65 − 60) / 5 = 1\'dir. Yeni not 70 + 1 · 10 = 80 olur.'),
];
